CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE app_state(key TEXT PRIMARY KEY,value BLOB NOT NULL,content_hash TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE journal_sources(source_id TEXT PRIMARY KEY,canonical_path TEXT NOT NULL,file_identity TEXT NOT NULL,fingerprint_head BLOB,fingerprint_anchor BLOB,observed_size INTEGER NOT NULL,committed_offset INTEGER NOT NULL DEFAULT 0,committed_sequence INTEGER NOT NULL DEFAULT 0,discard INTEGER NOT NULL DEFAULT 0,first_seen_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'verified',context_fid TEXT,context_session TEXT,context_system TEXT);
CREATE INDEX sources_path ON journal_sources(canonical_path,file_identity);
CREATE TABLE commander(fid TEXT PRIMARY KEY,latest_name TEXT,updated_at TEXT);
CREATE TABLE commander_names(fid TEXT REFERENCES commander(fid),name TEXT NOT NULL,from_utc TEXT NOT NULL,to_utc TEXT,PRIMARY KEY(fid,name,from_utc));
CREATE TABLE game_sessions(session_id TEXT PRIMARY KEY,commander_fid TEXT REFERENCES commander(fid),file_id TEXT REFERENCES journal_sources(source_id),start_utc TEXT,end_utc TEXT,game_version TEXT,galaxy TEXT);
CREATE TABLE journal_events(event_id INTEGER PRIMARY KEY,source_id TEXT NOT NULL REFERENCES journal_sources(source_id),byte_offset INTEGER NOT NULL,byte_length INTEGER NOT NULL,record_sequence INTEGER NOT NULL,line_hash TEXT NOT NULL,event_utc TEXT,type TEXT NOT NULL,commander_fid TEXT REFERENCES commander(fid),session_id TEXT REFERENCES game_sessions(session_id),system_address TEXT,raw_relevant_json TEXT NOT NULL,ingested_at TEXT NOT NULL,UNIQUE(source_id,byte_offset,line_hash));
CREATE INDEX events_source_offset ON journal_events(source_id,byte_offset);
CREATE INDEX events_commander_time ON journal_events(commander_fid,event_utc,event_id);
CREATE INDEX events_type_time ON journal_events(type,event_utc,event_id);
CREATE TABLE systems(system_address TEXT PRIMARY KEY,name TEXT NOT NULL,x REAL,y REAL,z REAL);
CREATE TABLE system_aliases(system_address TEXT REFERENCES systems(system_address),name TEXT NOT NULL,PRIMARY KEY(system_address,name));
CREATE TABLE system_visits(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),system_address TEXT NOT NULL REFERENCES systems(system_address),event_utc TEXT,source_event_id INTEGER UNIQUE REFERENCES journal_events(event_id));
CREATE INDEX visits_commander_system_time ON system_visits(commander_fid,system_address,event_utc);
CREATE TABLE ship_instances(commander_fid TEXT REFERENCES commander(fid),ship_id TEXT NOT NULL,model TEXT,custom_name TEXT,owner_state TEXT,last_location TEXT,last_seen TEXT,PRIMARY KEY(commander_fid,ship_id));
CREATE TABLE ship_loadout_snapshots(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),ship_id TEXT NOT NULL,source_event_id INTEGER UNIQUE REFERENCES journal_events(event_id),observed_at TEXT,reported_mass REAL,reported_jump_range REAL,fuel REAL,rebuy REAL,raw_json TEXT NOT NULL,FOREIGN KEY(commander_fid,ship_id) REFERENCES ship_instances(commander_fid,ship_id));
CREATE INDEX loadout_commander_ship_time ON ship_loadout_snapshots(commander_fid,ship_id,observed_at);
CREATE TABLE ship_module_snapshots(id INTEGER PRIMARY KEY,loadout_id INTEGER NOT NULL REFERENCES ship_loadout_snapshots(id),slot TEXT NOT NULL,module_symbol TEXT NOT NULL,on_state INTEGER,priority INTEGER,engineering_blueprint TEXT,engineering_grade REAL,experimental TEXT,UNIQUE(loadout_id,slot));
CREATE TABLE ship_module_modifiers(module_snapshot_id INTEGER NOT NULL REFERENCES ship_module_snapshots(id),label TEXT NOT NULL,effective_value REAL,original_value REAL,less_is_good INTEGER,raw_type TEXT,PRIMARY KEY(module_snapshot_id,label));
CREATE TABLE body_observations(system_address TEXT NOT NULL,body_id TEXT NOT NULL,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER NOT NULL REFERENCES journal_events(event_id),observed_at TEXT,raw_json TEXT NOT NULL,PRIMARY KEY(system_address,body_id,commander_fid,source_event_id));
CREATE INDEX body_system_id ON body_observations(system_address,body_id);
CREATE TABLE external_snapshots(id INTEGER PRIMARY KEY,provider TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,commander_fid TEXT,source_observed_at TEXT,fetched_at TEXT NOT NULL,expires_at TEXT,identity_verified INTEGER NOT NULL,content_hash TEXT NOT NULL,normalized_fields TEXT NOT NULL);
CREATE INDEX external_provider_entity_time ON external_snapshots(provider,entity_id,fetched_at);
CREATE TABLE field_provenance(id INTEGER PRIMARY KEY,entity TEXT NOT NULL,field TEXT NOT NULL,commander_fid TEXT,source TEXT NOT NULL,source_ref TEXT,observed_at TEXT,fetched_at TEXT,confidence TEXT NOT NULL,stale INTEGER NOT NULL,value_json TEXT NOT NULL);
CREATE INDEX provenance_entity_field ON field_provenance(commander_fid,entity,field,observed_at);
CREATE TABLE provider_requests(id INTEGER PRIMARY KEY,provider TEXT NOT NULL,kind TEXT NOT NULL,requested_at TEXT NOT NULL,outcome TEXT NOT NULL);
CREATE TABLE provider_consent(provider TEXT PRIMARY KEY,config_json TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE publication_policy(commander_fid TEXT PRIMARY KEY REFERENCES commander(fid),mode TEXT NOT NULL CHECK(mode IN ('Never','Live','After sale')),updated_at TEXT NOT NULL);
CREATE TABLE publication_exceptions(commander_fid TEXT REFERENCES commander(fid),provider TEXT NOT NULL,category TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(commander_fid,provider,category));
CREATE TABLE publication_candidates(id INTEGER PRIMARY KEY,source_event_id INTEGER NOT NULL REFERENCES journal_events(event_id),commander_fid TEXT NOT NULL REFERENCES commander(fid),provider TEXT NOT NULL,category TEXT NOT NULL,status TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(source_event_id,provider,category));
CREATE INDEX candidates_commander_status_provider ON publication_candidates(commander_fid,status,provider);
CREATE TABLE publication_attempts(id INTEGER PRIMARY KEY,candidate_id INTEGER NOT NULL REFERENCES publication_candidates(id),attempted_at TEXT NOT NULL,receipt_hash TEXT,outcome TEXT NOT NULL);
CREATE TABLE sale_item_links(sale_event_id INTEGER REFERENCES journal_events(event_id),observation_event_id INTEGER REFERENCES journal_events(event_id),confidence TEXT NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(sale_event_id,observation_event_id));
CREATE TABLE inventory_snapshots(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX inventory_snapshots_commander_time ON inventory_snapshots(commander_fid,observed_at,id);
CREATE TABLE materials_snapshots(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX materials_snapshots_commander_time ON materials_snapshots(commander_fid,observed_at,id);
CREATE TABLE cargo_snapshots(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX cargo_snapshots_commander_time ON cargo_snapshots(commander_fid,observed_at,id);
CREATE TABLE stored_ships(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX stored_ships_commander_time ON stored_ships(commander_fid,observed_at,id);
CREATE TABLE stored_modules(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX stored_modules_commander_time ON stored_modules(commander_fid,observed_at,id);
CREATE TABLE exploration_scans(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX exploration_scans_commander_time ON exploration_scans(commander_fid,observed_at,id);
CREATE TABLE bio_samples(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX bio_samples_commander_time ON bio_samples(commander_fid,observed_at,id);
CREATE TABLE bio_completed(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX bio_completed_commander_time ON bio_completed(commander_fid,observed_at,id);
CREATE TABLE exploration_sales(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX exploration_sales_commander_time ON exploration_sales(commander_fid,observed_at,id);
CREATE TABLE organic_sales(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX organic_sales_commander_time ON organic_sales(commander_fid,observed_at,id);
CREATE TABLE mission_history(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX mission_history_commander_time ON mission_history(commander_fid,observed_at,id);
CREATE TABLE transactions(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX transactions_commander_time ON transactions(commander_fid,observed_at,id);
CREATE TABLE powerplay_history(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX powerplay_history_commander_time ON powerplay_history(commander_fid,observed_at,id);
CREATE TABLE squadron_history(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX squadron_history_commander_time ON squadron_history(commander_fid,observed_at,id);
CREATE TABLE bgs_observations(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX bgs_observations_commander_time ON bgs_observations(commander_fid,observed_at,id);
CREATE TABLE colonisation_contributions(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX colonisation_contributions_commander_time ON colonisation_contributions(commander_fid,observed_at,id);
CREATE TABLE colonisation_commodity_snapshots(id INTEGER PRIMARY KEY,commander_fid TEXT NOT NULL REFERENCES commander(fid),source_event_id INTEGER UNIQUE NOT NULL REFERENCES journal_events(event_id),entity_id TEXT,system_address TEXT,observed_at TEXT,source TEXT NOT NULL DEFAULT 'journal',raw_json TEXT NOT NULL);
CREATE INDEX colonisation_commodity_snapshots_commander_time ON colonisation_commodity_snapshots(commander_fid,observed_at,id);
CREATE TABLE colonisation_projects(commander_fid TEXT REFERENCES commander(fid),market_id TEXT NOT NULL,system_address TEXT,construction_progress REAL,complete INTEGER,failed INTEGER,observed_at TEXT,source_event_id INTEGER REFERENCES journal_events(event_id),PRIMARY KEY(commander_fid,market_id));
